mapper.insert:
INSERT INTO attendance_report_export_artifact (
    attendance_report_export_id,
    content,
    created_at
) VALUES (
    #{exportId},
    #{content},
    #{createdAt}
)

mapper.select:
SELECT ,
       NULL AS content
FROM attendance_report_export_job job
WHERE job.attendance_report_export_id = #{exportId}
  AND job.principal_id = #{principalId}

SELECT ,
       artifact.content
FROM attendance_report_export_job job
JOIN attendance_report_export_artifact artifact
  ON artifact.attendance_report_export_id =
     job.attendance_report_export_id
WHERE job.attendance_report_export_id = #{exportId}
  AND job.principal_id = #{principalId}
  AND job.status = 'READY'
  AND job.expires_at > #{readAt}
  AND job.query_fingerprint = #{expectedQueryFingerprint}
  AND job.visible_content_digest =
      #{expectedVisibleContentDigest}

mapper.delete:
DELETE FROM attendance_report_export_job
WHERE expires_at <= #{expiredAt}
  AND status IN ('QUEUED', 'READY', 'FAILED')
ORDER BY expires_at, attendance_report_export_id
LIMIT #{limit}
